let nivel = context.get('nivel') || 50;
let bomba = context.get('bomba') || false;

if (bomba) {
    nivel += 5;
} else {
    nivel -= 2;
}

nivel = Math.max(0, Math.min(100, nivel));

context.set('nivel', nivel);

msg.payload = {
    nivel: nivel,
    bomba: bomba
};

return msg;

let nivel = msg.payload.nivel;
let bomba = msg.payload.bomba;

if (nivel < 30) {
    bomba = true;
}
if (nivel > 80) {
    bomba = false;
}

context.set('bomba', bomba);

msg.payload.bomba = bomba;
return msg;
